@page "/"

@inject IShipmentService ShipmentService

<PageTitle>Track Your Shipment</PageTitle>

<h1>Track Your Shipment</h1>
<p class="lead">Enter your tracking number to see the current status and estimated delivery.</p>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="e.g. TRK-20260601-001"
                   @bind="trackingInput" @bind:event="oninput"
                   @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="TrackShipment" disabled="@isLoading">
                @if (isLoading)
                {
                    <span class="spinner-border spinner-border-sm me-1" role="status"></span>
                }
                Track
            </button>
        </div>
    </div>
</div>

@if (searched && shipment is null)
{
    <div class="alert alert-warning">
        No shipment found for tracking number <strong>@searchedTracking</strong>. Please check the number and try again.
    </div>
}

@if (shipment is not null)
{
    <div class="card">
        <div class="card-header">
            <h5 class="mb-0">Shipment @shipment.TrackingNumber</h5>
        </div>
        <div class="card-body">
            <div class="row">
                <div class="col-md-6">
                    <dl>
                        <dt>Status</dt>
                        <dd><span class="badge @GetStatusBadgeClass(shipment.Status)">@FormatStatus(shipment.Status)</span></dd>
                        <dt>Recipient</dt>
                        <dd>@shipment.RecipientName</dd>
                    </dl>
                </div>
                <div class="col-md-6">
                    <dl>
                        <dt>From</dt>
                        <dd>@shipment.Origin</dd>
                        <dt>To</dt>
                        <dd>@shipment.Destination</dd>
                        <dt>Shipped</dt>
                        <dd>@shipment.ShippedDate.ToString("MMM dd, yyyy")</dd>
                        <dt>Estimated Delivery</dt>
                        <dd><strong>@shipment.EstimatedDelivery.ToString("MMM dd, yyyy")</strong></dd>
                    </dl>
                </div>
            </div>
            @if (!string.IsNullOrWhiteSpace(shipment.Notes))
            {
                <div class="alert alert-info mt-2 mb-0">@shipment.Notes</div>
            }
        </div>
    </div>
}

@code {
    private string trackingInput = string.Empty;
    private string searchedTracking = string.Empty;
    private Shipment? shipment;
    private bool searched;
    private bool isLoading;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter")
            await TrackShipment();
    }

    private async Task TrackShipment()
    {
        var trimmed = trackingInput.Trim();
        if (string.IsNullOrWhiteSpace(trimmed))
            return;

        isLoading = true;
        searchedTracking = trimmed;
        shipment = await ShipmentService.GetByTrackingNumberAsync(trimmed);
        searched = true;
        isLoading = false;
    }

    private static string FormatStatus(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "Pending",
        ShipmentStatus.PickedUp => "Picked Up",
        ShipmentStatus.InTransit => "In Transit",
        ShipmentStatus.OutForDelivery => "Out for Delivery",
        ShipmentStatus.Delivered => "Delivered",
        ShipmentStatus.Exception => "Exception",
        _ => status.ToString()
    };

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentStatus.PickedUp => "bg-secondary",
        ShipmentStatus.Pending => "bg-warning text-dark",
        ShipmentStatus.Exception => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/dashboard"
@attribute [Authorize]

@inject IShipmentService ShipmentService

<PageTitle>Dispatcher Dashboard</PageTitle>

<h1>Dispatcher Dashboard</h1>

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else
{
    <div class="row mb-3">
        <div class="col-md-4">
            <input type="text" class="form-control" placeholder="Filter by destination..."
                   @bind="filterText" @bind:event="oninput" />
        </div>
        <div class="col-md-3">
            <select class="form-select" @bind="statusFilter">
                <option value="">All Statuses</option>
                @foreach (var s in Enum.GetValues<ShipmentStatus>())
                {
                    <option value="@s">@FormatStatus(s)</option>
                }
            </select>
        </div>
    </div>

    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead class="table-dark">
                <tr>
                    <th>Tracking #</th>
                    <th>Recipient</th>
                    <th>Origin</th>
                    <th>Destination</th>
                    <th>Shipped</th>
                    <th>Est. Delivery</th>
                    <th>Status</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><code>@s.TrackingNumber</code></td>
                        <td>@s.RecipientName</td>
                        <td>@s.Origin</td>
                        <td>@s.Destination</td>
                        <td>@s.ShippedDate.ToString("MMM dd")</td>
                        <td>@s.EstimatedDelivery.ToString("MMM dd")</td>
                        <td><span class="badge @GetStatusBadgeClass(s.Status)">@FormatStatus(s.Status)</span></td>
                        <td>
                            <select class="form-select form-select-sm" style="width: auto; display: inline-block;"
                                    value="@((int)s.Status)"
                                    @onchange="e => UpdateStatus(s, e)">
                                @foreach (var status in Enum.GetValues<ShipmentStatus>())
                                {
                                    <option value="@((int)status)">@FormatStatus(status)</option>
                                }
                            </select>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>

    @if (!FilteredShipments.Any())
    {
        <div class="alert alert-info">No shipments match your filters.</div>
    }
}

@code {
    private List<Shipment>? shipments;
    private string filterText = string.Empty;
    private string statusFilter = string.Empty;

    private IEnumerable<Shipment> FilteredShipments =>
        (shipments ?? [])
            .Where(s => string.IsNullOrWhiteSpace(filterText)
                || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)
                || s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase))
            .Where(s => string.IsNullOrWhiteSpace(statusFilter)
                || s.Status.ToString() == statusFilter);

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private async Task UpdateStatus(Shipment shipment, ChangeEventArgs e)
    {
        if (Enum.TryParse<ShipmentStatus>(e.Value?.ToString(), out var newStatus))
        {
            await ShipmentService.UpdateStatusAsync(shipment.Id, newStatus);
            shipment.Status = newStatus;
        }
    }

    private static string FormatStatus(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Pending => "Pending",
        ShipmentStatus.PickedUp => "Picked Up",
        ShipmentStatus.InTransit => "In Transit",
        ShipmentStatus.OutForDelivery => "Out for Delivery",
        ShipmentStatus.Delivered => "Delivered",
        ShipmentStatus.Exception => "Exception",
        _ => status.ToString()
    };

    private static string GetStatusBadgeClass(ShipmentStatus status) => status switch
    {
        ShipmentStatus.Delivered => "bg-success",
        ShipmentStatus.InTransit => "bg-primary",
        ShipmentStatus.OutForDelivery => "bg-info text-dark",
        ShipmentStatus.PickedUp => "bg-secondary",
        ShipmentStatus.Pending => "bg-warning text-dark",
        ShipmentStatus.Exception => "bg-danger",
        _ => "bg-secondary"
    };
}

